import type { Contract } from './contract-model';
import type { Workspace } from './workspace-model';

export const ContractComplianceDetailSignatureStatusKeyToLabel = {
  'NotStarted': 'NotStarted',
  'InProgress': 'InProgress',
  'FullySigned': 'FullySigned',
  'Declined': 'Declined'
} as const;
export type ContractComplianceDetailSignatureStatusKey = keyof typeof ContractComplianceDetailSignatureStatusKeyToLabel;

export interface ContractComplianceDetail {
  /**
   * @displayName Contract Compliance Detail ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Detail Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  detailName: string;
  /**
   * @displayName Confidentiality Required
   * @validationRule Required for create/update operations
   */
  confidentialityRequired: boolean;
  /**
   * @displayName Contract
   * @validationRule Required for create/update operations
   */
  contract: Pick<Contract, 'id' | 'title'>;
  /**
   * @displayName Cost Center
   * @validationRule Required for create/update operations
   */
  costCenter: string;
  /**
   * @displayName Data Protection Required
   * @validationRule Required for create/update operations
   */
  dataProtectionRequired: boolean;
  /**
   * @displayName Document URL
   */
  documentURL?: string;
  /**
   * @displayName Insurance Expiry Date
   */
  insuranceExpiryDate?: string;
  /**
   * @displayName Insurance Required
   * @validationRule Required for create/update operations
   */
  insuranceRequired: boolean;
  /**
   * @displayName Liability Cap Amount
   */
  liabilityCapAmount?: number;
  /**
   * @displayName Procurement Reference
   */
  procurementReference?: string;
  /**
   * @displayName Purchase Order Number
   */
  purchaseOrderNumber?: string;
  /**
   * @displayName Signature Status
   * @validationRule Required for create/update operations
   */
  signatureStatusKey: ContractComplianceDetailSignatureStatusKey;
  /**
   * @displayName Signed Date
   */
  signedDate?: string;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _ContractComplianceDetail = 'ContractComplianceDetail' as const;